-- DQ-005: ER Status Domain---- Purpose:-- Validate the observed values of the ER.Status variable-- in the staging layer.---- Expected categories:-- - Positive-- - Negative-- - NULL-- - Not Performed-- - Performed but Not Available-- - Indeterminate---- Expected record counts:-- - Positive = 414-- - Negative = 135-- - NULL = 122-- - Not Performed = 27-- - Performed but Not Available = 5-- - Indeterminate = 2-- - Total records = 705---- This validation does not modify the data.SELECT    "ER.Status",    COUNT(*) AS quantityFROM staging.brca_sample_wideGROUP BY "ER.Status"ORDER BY quantity DESC;